import { SelfAppBuilder, getUniversalLink } from '@selfxyz/sdk-common';
import type { SoftKycRequirements, VerificationRequest } from './types.js';

/**
 * The Celo chain the Self hub for an endpoint type lives on. A `staging_*`
 * endpoint registers mock identities on Celo Sepolia (11142220); a production
 * one on Celo mainnet (42220). The SDK derives `chainID` from `staging_celo`
 * ALONE, so a `staging_https` receiver silently gets 42220 and a mock passport,
 * which registered on Sepolia, never matches: the Self app hangs at "Preparing
 * for verification" and never posts. Setting it here removes that contradiction
 * (celo-org/cpay#75).
 */
export function chainIdForEndpointType(endpointType: string | undefined): 11142220 | 42220 {
  return endpointType?.startsWith('staging_') ? 11142220 : 42220;
}

/** Translates our compact requirements shape into the Self disclosures schema. */
function toDisclosures(req: SoftKycRequirements) {
  const disclosures: Record<string, unknown> = {};
  if (req.minimumAge !== undefined) disclosures.minimumAge = req.minimumAge;
  if (req.excludedCountries?.length) disclosures.excludedCountries = req.excludedCountries;
  if (req.notOfac !== undefined) disclosures.ofac = req.notOfac;
  if (req.discloseNationality) disclosures.nationality = true;
  if (req.discloseGender) disclosures.gender = true;
  return disclosures;
}

/**
 * Build a Self verification request and return the universal link the mobile
 * app understands. The link is what gets rendered as a QR code in the terminal.
 *
 * The builder comes from Self's framework-neutral package. Importing the UI
 * package here used to initialize its WebSocket client on every CLI startup.
 */
export async function buildVerificationLink(request: VerificationRequest): Promise<string> {
  const app = new SelfAppBuilder({
    version: 2,
    appName: request.appName,
    scope: request.scope,
    endpoint: request.endpoint,
    endpointType: request.endpointType,
    // Derived from the endpoint type, not left to the SDK default, which maps
    // only `staging_celo` to Sepolia and sends `staging_https` to mainnet.
    chainID: chainIdForEndpointType(request.endpointType),
    userId: request.userId,
    userIdType: 'hex',
    userDefinedData: request.userDefinedData ?? '',
    disclosures: toDisclosures(request.requirements),
  }).build();
  return getUniversalLink(app);
}

/** Exposed for tests — pure function, no Self SDK calls. */
export function _disclosuresFor(req: SoftKycRequirements) {
  return toDisclosures(req);
}
