import qrcode from 'qrcode-terminal';

export type QrRenderOptions = {
  small?: boolean;
};

/**
 * Render the Self universal link as an ASCII QR code suitable for a 80-col
 * terminal. `small` halves the size at the cost of legibility on noisy
 * displays.
 */
export function renderQrToTerminal(link: string, opts: QrRenderOptions = {}): Promise<string> {
  return new Promise((resolve) => {
    qrcode.generate(link, { small: opts.small ?? true }, (out) => resolve(out));
  });
}

/**
 * A note to print beside a QR that will not fit the terminal.
 *
 * A Self verification QR is ~47 rows even at `small: true` — the link it
 * encodes is ~660 characters — so a default 24-row terminal scrolls the top
 * half away and leaves something that cannot be scanned. Nothing about the
 * output says so: it simply does not work, and the reader has no idea why.
 *
 * Returns undefined when it fits, or when the height is unknown (not a TTY, so
 * nobody is looking at it anyway).
 */
export function qrFitWarning(
  qr: string,
  rows: number | undefined = process.stdout.rows,
): string | undefined {
  if (!rows) return undefined;
  const needed = qr.split('\n').length;
  // A couple of rows of slack for the prompt and the lines printed with it.
  if (needed + 2 <= rows) return undefined;
  return `This QR needs about ${needed} rows and your terminal has ${rows}. Enlarge the window and run the command again, or open the link below on the phone directly.`;
}
