import { createHash } from 'node:crypto';
import type { VerificationAttributes } from '@celo/buy-keystore';
import { AllIds, DefaultConfigStore, SelfBackendVerifier } from '@selfxyz/core';
import type {
  SoftKycRequirements,
  VerificationFailure,
  VerificationRequest,
  VerificationResult,
} from './types.js';

export type ProofPayload = {
  attestationId: number;
  proof: unknown;
  publicSignals: unknown;
  userContextData: unknown;
};

function hashProof(proof: ProofPayload): string {
  const hex = createHash('sha256').update(JSON.stringify(proof)).digest('hex');
  return `0x${hex}`;
}

function cleanDisclosedString(value: unknown): string | undefined {
  if (typeof value !== 'string') return undefined;
  // biome-ignore lint/suspicious/noControlCharactersInRegex: intentionally strips null-byte padding that Self.xyz SDK returns for undisclosed fields
  const trimmed = value.replace(/\u0000+/g, '').trim();
  return trimmed.length > 0 ? trimmed : undefined;
}

function attributesFromDisclosures(
  req: SoftKycRequirements,
  disclosed: Record<string, unknown>,
): VerificationAttributes {
  const attrs: VerificationAttributes = {};
  if (req.minimumAge !== undefined) attrs.minimumAge = req.minimumAge;
  if (req.notOfac) attrs.notOfac = true;
  if (req.excludedCountries?.length) attrs.excludedCountries = req.excludedCountries;
  if (req.discloseNationality) {
    const nationality = cleanDisclosedString(disclosed.nationality);
    if (nationality !== undefined) attrs.nationality = nationality;
  }
  if (req.discloseGender) {
    const gender = cleanDisclosedString(disclosed.gender);
    if (gender !== undefined) attrs.gender = gender;
  }
  return attrs;
}

/**
 * Verify a Self proof against the requested requirements. Wraps Self's
 * `SelfBackendVerifier` and translates its result into a compact attestation
 * we can persist to accounts.json.
 *
 * NOTE: SelfBackendVerifier hits an on-chain hub for some checks. We don't
 * currently expose a custom hub address — the SDK defaults to mainnet /
 * staging based on the network choice baked into the proof itself.
 */
/**
 * Decode the hex `userDefinedData` tail back to the string that was sent.
 *
 * STRICT, and deliberately so. `Buffer.from(hex, 'hex').toString('utf8')`
 * silently maps every invalid byte sequence to U+FFFD, so a caller comparing
 * decoded values would see distinct proofs collapse onto one key — which, for
 * anything using this to identify a session, is a collision an attacker picks.
 * `TextDecoder` in fatal mode refuses instead, and `undefined` means "no usable
 * value" rather than a lossy guess. Anything needing exactness compares
 * `userDefinedDataHex`.
 */
export function decodeUserDefinedData(hex: string | undefined): string | undefined {
  if (hex === undefined) return undefined;
  const clean = hex.startsWith('0x') ? hex.slice(2) : hex;
  // The SDK returns '' when the request carried no userDefinedData.
  if (clean === '') return undefined;
  if (clean.length % 2 !== 0 || !/^[0-9a-fA-F]+$/.test(clean)) return undefined;
  try {
    return new TextDecoder('utf-8', { fatal: true }).decode(Buffer.from(clean, 'hex'));
  } catch {
    return undefined;
  }
}

/**
 * Verify against BOTH Self hubs when the caller will accept either.
 *
 * A `SelfBackendVerifier` is bound to one hub: `mockPassport` picks the RPC and
 * the IdentityVerificationHub address, staging or mainnet. A mock passport
 * registers its identity root on staging and a real one on mainnet, so a single
 * verifier can only ever validate one of them — the other fails with
 * `InvalidRoot: Onchain root does not exist`, an error about WHERE the root was
 * looked for, not about the proof being bad.
 *
 * Trying both is what lets one deployment serve testers with mock
 * passports and real users at the same time. It costs an extra hub read
 * only on the miss, and it is safe because the two cannot be confused: the
 * scope commitment is `hashEndpointWithScope(endpoint, scope)` — endpointType
 * is NOT in it — so a proof that validates against a hub validates for this
 * exact endpoint and scope regardless of which hub held its root.
 *
 * The hub that succeeded comes back as `usedMockPassport`, because the
 * attestation has to record the matching `endpointType` or re-verification
 * later would look in the wrong place.
 */
export async function verifyProof(
  request: VerificationRequest,
  payload: ProofPayload,
): Promise<VerificationResult | VerificationFailure> {
  if (request.mockPassport !== 'either') {
    return verifyAgainstHub(request, payload, request.mockPassport);
  }
  // Try the hub the QR pointed at first: on the common path that is a hit, and
  // the fallback is only paid by whoever is using the other kind of passport.
  const first = request.endpointType?.startsWith('staging_') === true;
  const primary = await verifyAgainstHub(request, payload, first);
  if (primary.ok) return primary;
  const secondary = await verifyAgainstHub(request, payload, !first);
  if (secondary.ok) return secondary;
  // Report the PRIMARY failure. The secondary is almost always
  // "root does not exist", which describes the fallback attempt rather than
  // anything wrong with the proof, and would bury the real reason.
  return primary;
}

async function verifyAgainstHub(
  request: VerificationRequest,
  payload: ProofPayload,
  mockPassport: boolean,
): Promise<VerificationResult | VerificationFailure> {
  // SDK enforces a narrow Country3LetterCode union — we accept any string at
  // our surface (so callers can pass ISO-3 codes directly) and cast here.
  const configStore = new DefaultConfigStore({
    minimumAge: request.requirements.minimumAge,
    excludedCountries: request.requirements.excludedCountries as never,
    ofac: request.requirements.notOfac ?? false,
  });

  const verifier = new SelfBackendVerifier(
    request.scope,
    request.endpoint,
    mockPassport,
    AllIds,
    configStore,
    'hex',
  );

  try {
    const result = (await verifier.verify(
      // SDK types attestationId as a literal union (1 | 2 | 3). Self mobile
      // sends a number — we trust whatever the proof carried.
      payload.attestationId as 1 | 2 | 3,
      payload.proof as never,
      payload.publicSignals as never,
      payload.userContextData as never,
    )) as {
      isValidDetails?: { isValid?: boolean };
      discloseOutput?: Record<string, unknown>;
      userData?: { userIdentifier?: string; userDefinedData?: string };
      nullifier?: string;
    };

    const ok = result.isValidDetails?.isValid === true;
    if (!ok) {
      return { ok: false, reason: 'Self verifier returned isValid=false' };
    }
    const disclosed = result.discloseOutput ?? {};
    const nullifier =
      result.nullifier ??
      (typeof disclosed.nullifier === 'string' ? disclosed.nullifier : undefined);
    return {
      ok: true,
      attributes: attributesFromDisclosures(request.requirements, disclosed),
      proofHash: hashProof(payload),
      userIdentifier: result.userData?.userIdentifier,
      nullifier,
      // Carried through from `userContextData`, whose sha256 the circuit commits
      // to as a public signal — so a value the VERIFIER placed in the request
      // comes back provably unmodified. That is what lets a receiver serving
      // many unknown callers tell which pending session a proof belongs to; a
      // single-session receiver never needed to ask, which is why this was
      // dropped on the floor until now.
      //
      // It arrives HEX-ENCODED, and it is worth being explicit about why. The
      // request side packs it with `ethers.solidityPacked([..., 'bytes'],
      // [..., toUtf8Bytes(userDefinedData)])`, and `SelfBackendVerifier` hands
      // back `userContextData.slice(128)` — the raw hex tail, undecoded and
      // unpadded. So `'session-xyz'` returns as `'73657373696f6e2d78797a'`.
      // Both forms are exposed: the hex is what an identity comparison should
      // use, and the decoded string is what everything else wants.
      userDefinedDataHex: result.userData?.userDefinedData,
      userDefinedData: decodeUserDefinedData(result.userData?.userDefinedData),
      // Which hub actually held this identity's root. The attestation records
      // the matching endpointType so re-verification looks in the same place.
      usedMockPassport: mockPassport,
    };
  } catch (err) {
    return { ok: false, reason: err instanceof Error ? err.message : String(err) };
  }
}

/**
 * Build a mock attestation result with no Self SDK calls. Used by `buy
 * verify mock` for demos and CI smoke tests where running the mobile-app
 * flow isn't practical.
 */
export function buildMockResult(request: VerificationRequest): VerificationResult {
  return {
    ok: true,
    attributes: attributesFromDisclosures(request.requirements, {}),
    proofHash: `0xmock${Buffer.from(request.scope).toString('hex')}`,
  };
}
