import type { Verification } from '@celo/buy-keystore';
import type { VerificationRequest } from './types.js';

/**
 * The wire protocol between a client and a gateway that hosts the Self
 * receiver for it (celo-org/cpay#63).
 *
 * These live in the shared package rather than beside either end because they
 * describe a TRUST BOUNDARY. The gateway recovers a signature over
 * `sessionMintMessage`; the client produces one. If the two strings ever drift
 * the failure is a 401 with no indication that the message format is why, so
 * there is exactly one definition and both sides import it.
 *
 * The challenge itself is deliberately NOT here: it is an HMAC under a secret
 * only the gateway holds, and a client that could compute one could mint its
 * own. The client receives a challenge and echoes it back, nothing more.
 */

/** Where a client asks the gateway for a verification session. */
export const SELF_SESSION_ROUTE = '/self/session';
/** Where a client asks for a challenge to sign. */
export const SELF_CHALLENGE_ROUTE = `${SELF_SESSION_ROUTE}/challenge`;
/** Where a verified wallet fetches its own attestation back. */
export const SELF_ATTESTATION_ROUTE = '/self/attestation';

/**
 * What a wallet signs to mint a verification session.
 *
 * Domain-separated and versioned so a signature harvested here cannot be
 * replayed as anything else, and bound to a CHALLENGE so it cannot be replayed
 * as this either — without one the message is constant for a given
 * (address, scope) and a single captured signature mints sessions forever.
 */
export function sessionMintMessage(
  address: string,
  scope: string,
  challenge: string,
  gatewayOrigin: string,
): string {
  return `cpay-self-session:v2:${gatewayOrigin}:${address.toLowerCase()}:${scope}:${challenge}`;
}

/**
 * What a wallet signs to fetch its own attestation back.
 *
 * A DIFFERENT prefix from `sessionMintMessage` on purpose. The two routes are
 * signed by the same key for the same scope, so without domain separation a
 * signature captured from one is a valid signature for the other.
 *
 * BOUND TO THE GATEWAY, which is what stops a relay. Any resource server can
 * put its own URL in `selfRequirements.endpoint`, and the printed remedy tells
 * the user to run `buy verify hosted --endpoint <that url>` — so a hostile one
 * can proxy a real gateway's challenge, answer `verified` without any proof
 * existing, and collect a signature. Without the origin in the string that
 * signature is valid at the REAL gateway, and replaying it returns the
 * victim's disclosed age, nationality, OFAC standing and raw proof payload.
 * With it, a signature produced for one gateway is meaningless at another.
 */
export function attestationFetchMessage(
  address: string,
  scope: string,
  challenge: string,
  gatewayOrigin: string,
): string {
  return `cpay-self-fetch:v2:${gatewayOrigin}:${address.toLowerCase()}:${scope}:${challenge}`;
}

/**
 * The gateway origin a pinned receiver URL belongs to.
 *
 * The 402 pins the RECEIVER (`https://gw.example/self/api/verify`); the session
 * and attestation routes hang off the gateway ROOT. Deriving one from the other
 * means a client is never asked to configure two URLs that must agree.
 */
export function gatewayOriginFor(receiverUrl: string): string {
  return new URL(receiverUrl).origin;
}

/* ------------------------------------------------------------------------- *
 * Client side of the protocol above.
 *
 * Lives here rather than in the CLI because `@celo/buy` publishes a `bin` and
 * no `main`, so nothing can import from it — including the tests that need to
 * drive this handshake against a real gateway.
 * ------------------------------------------------------------------------- */

export type MintedSession = {
  readonly sessionId: string;
  readonly endpoint: string;
  readonly endpointType: VerificationRequest['endpointType'];
  readonly scope: string;
  readonly userDefinedData: string;
  readonly disclosures?: { readonly minimumAge?: number; readonly ofac?: boolean };
};

/**
 * A JSON call that reports the gateway's own error text.
 *
 * Deliberately surfaces the body rather than just the status: every refusal on
 * these routes is a sentence a user can act on ("challenge is missing, expired,
 * or not ours"), and collapsing them to "HTTP 401" throws that away.
 */
/** A single request may not hang forever; the loop deadline cannot cut one short. */
const REQUEST_TIMEOUT_MS = 20_000;
/** A pinned gateway is chosen by the server, not the user — cap what it can return. */
const MAX_RESPONSE_BYTES = 512 * 1024;

async function gatewayJson(
  url: string,
  init: RequestInit | undefined,
  what: string,
): Promise<Record<string, unknown>> {
  let res: Response;
  try {
    // Without this a gateway that accepts the connection and never answers
    // parks the await forever: the poll deadline is only checked between
    // iterations, so `--timeout-seconds` would not bound the command at all.
    res = await fetch(url, { ...init, signal: AbortSignal.timeout(REQUEST_TIMEOUT_MS) });
  } catch (err) {
    // Marked TRANSIENT: the request never reached the gateway, so retrying is
    // meaningful. The poll loop leans on this — a momentary blip while waiting
    // must not discard a verification the user has already completed on their
    // phone, since recovering costs them another QR scan.
    const failure = new Error(
      `could not reach the gateway to ${what} (${url}): ${err instanceof Error ? err.message : String(err)}`,
    );
    (failure as Error & { transient?: boolean }).transient = true;
    throw failure;
  }
  const declared = Number(res.headers.get('content-length') ?? '0');
  if (declared > MAX_RESPONSE_BYTES) {
    throw new Error(`gateway sent an oversized response when asked to ${what}`);
  }
  const text = await res.text();
  if (text.length > MAX_RESPONSE_BYTES) {
    throw new Error(`gateway sent an oversized response when asked to ${what}`);
  }
  let body: Record<string, unknown> = {};
  try {
    body = text ? (JSON.parse(text) as Record<string, unknown>) : {};
  } catch {
    throw new Error(`gateway returned non-JSON when asked to ${what} (HTTP ${res.status})`);
  }
  if (!res.ok) {
    const detail = typeof body.error === 'string' ? body.error : `HTTP ${res.status}`;
    const failure = new Error(`gateway refused to ${what}: ${detail}`);
    // 429 is the gateway asking us to wait, not declining. Its mint limiter is
    // global, so honest callers hit it under load; treating that as fatal turns
    // ordinary contention into a failed verification.
    if (res.status === 429) (failure as Error & { transient?: boolean }).transient = true;
    throw failure;
  }
  return body;
}

/** Ask for a challenge and sign `message(challenge)` with the account key. */
async function signedFor(
  origin: string,
  address: string,
  message: (challenge: string, scope: string) => string,
  sign: (message: string) => Promise<string>,
  fallbackScope: string,
): Promise<{ challenge: string; signature: string; scope: string }> {
  const issued = await gatewayJson(
    `${origin}${SELF_CHALLENGE_ROUTE}?address=${encodeURIComponent(address)}`,
    undefined,
    'issue a challenge',
  );
  const challenge = issued.challenge;
  if (typeof challenge !== 'string') throw new Error('gateway issued no challenge');
  // The gateway's own scope wins: it is the side that reconstructs this message
  // to recover the signature, so signing with anything else fails as an
  // address mismatch and blames the wallet.
  const scope = typeof issued.scope === 'string' && issued.scope ? issued.scope : fallbackScope;
  return { challenge, signature: await sign(message(challenge, scope)), scope };
}

/**
 * The whole gateway handshake, with its I/O injected.
 *
 * Split from the command because the command's other half — resolving an
 * account and loading its key — reaches the OS keyring, which a temporary
 * `BUY_HOME` does NOT isolate. Everything security-relevant here is the
 * protocol (which message is signed, whether a fresh challenge is taken, what
 * happens when the session expires), so that part takes a `sign` function and
 * can be exercised against a real gateway without touching a keychain.
 */
export type HostedVerificationDeps = {
  readonly origin: string;
  readonly address: string;
  readonly scope: string;
  readonly sign: (message: string) => Promise<string>;
  readonly timeoutMs: number;
  readonly pollMs: number;
  /** Called once the session exists, with everything a QR needs. */
  readonly onSession?: (minted: MintedSession) => void | Promise<void>;
  readonly now?: () => number;
  readonly sleep?: (ms: number) => Promise<void>;
};

export async function runHostedVerification(deps: HostedVerificationDeps): Promise<Verification> {
  const now = deps.now ?? (() => Date.now());
  const sleep = deps.sleep ?? ((ms: number) => new Promise((r) => setTimeout(r, ms)));

  const { scope: _mintScope, ...mintAuth } = await signedFor(
    deps.origin,
    deps.address,
    (challenge, scope) => sessionMintMessage(deps.address, scope, challenge, deps.origin),
    deps.sign,
    deps.scope,
  );
  const minted = (await gatewayJson(
    `${deps.origin}${SELF_SESSION_ROUTE}`,
    {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ address: deps.address, ...mintAuth }),
    },
    'mint a verification session',
  )) as unknown as MintedSession;
  await deps.onSession?.(minted);

  const deadline = now() + deps.timeoutMs;
  let verified = false;
  while (now() < deadline) {
    await sleep(deps.pollMs);
    let polled: Record<string, unknown>;
    try {
      polled = await gatewayJson(
        `${deps.origin}${SELF_SESSION_ROUTE}/${minted.sessionId}`,
        undefined,
        'poll the session',
      );
    } catch (err) {
      // Only a failure to REACH the gateway is retried. A refusal is an answer:
      // a 404 means the session is gone, and looping on it would replace a
      // clear message with a long silence ending in a timeout.
      if ((err as Error & { transient?: boolean }).transient) continue;
      throw err;
    }
    if (polled.status === 'verified') {
      verified = true;
      break;
    }
    // Terminal: the session aged out and no proof can bind to it any more.
    if (polled.status === 'expired') throw new Error('the verification session expired');
  }
  // #6: the proof may already be stored — the fetch is keyed on ADDRESS, not on
  // the session — so one attempt before giving up turns a lost QR scan into a
  // success when the last poll merely landed a moment early.
  if (!verified) {
    const salvaged = await collectAttestation(deps).catch(() => undefined);
    if (salvaged) return salvaged;
    throw new Error(`timed out after ${deps.timeoutMs}ms waiting for the Self proof`);
  }
  return collectAttestation(deps);
}

async function collectAttestation(deps: HostedVerificationDeps): Promise<Verification> {
  // A FRESH challenge: the mint challenge may well have aged out during the
  // wait, and reusing it fails for a reason that has nothing to do with the user.
  const { scope: agreedScope, ...fetchAuth } = await signedFor(
    deps.origin,
    deps.address,
    (challenge, scope) => attestationFetchMessage(deps.address, scope, challenge, deps.origin),
    deps.sign,
    deps.scope,
  );
  const fetched = await gatewayJson(
    `${deps.origin}${SELF_ATTESTATION_ROUTE}`,
    {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ address: deps.address, ...fetchAuth }),
    },
    'fetch the attestation',
  );
  return checkedAttestation(fetched.attestation, deps, agreedScope);
}

/**
 * Refuse anything that is not this wallet's attestation for this scope.
 *
 * A gateway response is as untrusted as a header, and this one is written
 * straight into `accounts.json`. Storing a malformed object corrupts the
 * account file and surfaces much later; storing someone else's is refused at
 * purchase time as `binding_mismatch`, an error that points nowhere near here.
 */
function checkedAttestation(
  value: unknown,
  deps: HostedVerificationDeps,
  scope: string,
): Verification {
  if (typeof value !== 'object' || value === null) {
    throw new Error('gateway returned no attestation');
  }
  const a = value as Partial<Verification>;
  for (const field of ['provider', 'scope', 'proofHash', 'verifiedAt'] as const) {
    if (typeof a[field] !== 'string' || a[field] === '') {
      throw new Error(`gateway returned an attestation with no ${field}`);
    }
  }
  if (typeof a.attributes !== 'object' || a.attributes === null) {
    throw new Error('gateway returned an attestation with no attributes');
  }
  if (a.scope !== scope) {
    throw new Error(`gateway returned an attestation for scope "${a.scope}", not "${scope}"`);
  }
  if ((a.userIdentifier ?? '').toLowerCase() !== deps.address.toLowerCase()) {
    throw new Error('gateway returned an attestation bound to a different address');
  }
  return a as Verification;
}
